// 'Dormant' here means the Clio matter record itself hasn't been updated in a while -- not a true
// measure of client contact, since Clio has no firm-wide 'last client communication' field. It's a
// starting signal for a human to check in, not a precise measurement.
//
// Re-flags periodically (every DORMANT_THRESHOLD_DAYS again) rather than just once, since a matter
// that's STILL dormant a month after the first nudge is worth surfacing again -- tracked via n8n's
// own workflow static data, keyed by matter id.
const matter = $json;
const DORMANT_THRESHOLD_DAYS = Number($vars.DORMANT_THRESHOLD_DAYS || 90);

const updatedStr = matter.updated_at.includes('T') ? matter.updated_at : matter.updated_at + 'T12:00:00Z';
const updatedAt = new Date(updatedStr);
updatedAt.setHours(0, 0, 0, 0);
const today = new Date();
today.setHours(0, 0, 0, 0);
const msPerDay = 24 * 60 * 60 * 1000;
const daysSinceUpdate = Math.round((today - updatedAt) / msPerDay);
const isDormant = daysSinceUpdate >= DORMANT_THRESHOLD_DAYS;

const staticData = $getWorkflowStaticData('global');
if (!staticData.lastFlaggedAt) staticData.lastFlaggedAt = {};
const lastFlaggedAt = staticData.lastFlaggedAt[matter.id];
const cooldownMs = DORMANT_THRESHOLD_DAYS * 24 * 60 * 60 * 1000;
const offCooldown = !lastFlaggedAt || (Date.now() - new Date(lastFlaggedAt).getTime()) >= cooldownMs;
const needsAlert = isDormant && offCooldown;
if (needsAlert) staticData.lastFlaggedAt[matter.id] = new Date().toISOString();

return { json: {
  matter_id: matter.id,
  matter_ref: matter.display_number || '',
  matter_description: matter.description || '',
  client_name: (matter.client && matter.client.name) || '',
  days_since_update: daysSinceUpdate,
  attorney_name: (matter.responsible_attorney && matter.responsible_attorney.name) || '',
  attorney_email: (matter.responsible_attorney && matter.responsible_attorney.email) || $vars.FIRM_EMAIL,
  needs_alert: needsAlert,
} };

const m = $json;
const FIRM_NAME = $vars.FIRM_NAME || 'the firm';
const matterLabel = m.matter_ref + (m.matter_description ? ' (' + m.matter_description + ')' : '');
const subject = `Client gone quiet — ${matterLabel}`;
const message = `${m.client_name}'s matter (${matterLabel}) hasn't been updated in ${m.days_since_update} days. Worth a check-in call?\n\nThis is a good candidate for LegalContext's Dormant Follow-Up — it tracks true last-contact dates across email and calls, not just the matter record, and can help resurface work like this automatically.`;

return { json: {
  ...m,
  recipient: m.attorney_email,
  subject,
  message,
} };

// Anchors renewal_date at noon UTC before day-difference math to avoid the off-by-one-day bug on
// servers running west of UTC (same fix used for date math throughout this catalog). Fires once per
// tier and again every day once overdue, same escalation philosophy as PAC-67's Statute of
// Limitations Watchdog.
const row = $json;
const REMINDER_DAYS = Number($vars.RENEWAL_REMINDER_DAYS || 30);

const dateStr = row.renewal_date.includes('T') ? row.renewal_date : row.renewal_date + 'T12:00:00Z';
const renewalDate = new Date(dateStr);
renewalDate.setHours(0, 0, 0, 0);
const today = new Date();
today.setHours(0, 0, 0, 0);
const msPerDay = 24 * 60 * 60 * 1000;
const daysRemaining = Math.round((renewalDate - today) / msPerDay);

const isWithinWindow = daysRemaining <= REMINDER_DAYS;
const isOverdue = daysRemaining < 0;

const staticData = $getWorkflowStaticData('global');
if (!staticData.renewalAlertedAt) staticData.renewalAlertedAt = {};
const key = row.matter_ref + '|' + row.renewal_date;
const alreadyAlerted = !!staticData.renewalAlertedAt[key];

// Once inside the window, alert once -- except once overdue, alert every day until the sheet's
// renewal_date is updated to a future date (which naturally resets the dedupe key).
const needsAlert = isWithinWindow && (isOverdue || !alreadyAlerted);
if (needsAlert && !isOverdue) staticData.renewalAlertedAt[key] = new Date().toISOString();

return { json: { ...row, days_remaining: daysRemaining, is_overdue: isOverdue, needs_alert: needsAlert } };

const r = $json;
const daysPhrase = r.is_overdue ? `overdue by ${Math.abs(r.days_remaining)} day${Math.abs(r.days_remaining) === 1 ? '' : 's'}` : `${r.days_remaining} day${r.days_remaining === 1 ? '' : 's'} away`;
const subject = `${r.is_overdue ? 'OVERDUE — ' : ''}Renewal coming up — ${r.client_name}`;
const message = `${r.client_name} (${r.matter_ref}) has a renewal/filing date ${daysPhrase}: ${r.description}.\n\nDue: ${r.renewal_date}.`;
return { json: { ...r, recipient: r.attorney_email || $vars.FIRM_EMAIL, subject, message } };
